/*
 * The waitlisted speakers, added HIDDEN (ADR 0093).
 *
 * Six waitlisted sessions and seven people (one session has two speakers) are
 * appended to the live `speakers` and `sessions` collections with
 * `hidden: true`: kept ready, never shown on the public site. To bring one in
 * if a slot opens: Admin -> Speakers -> Show, and Admin -> Schedule -> Show
 * (then give the session a time).
 *
 * ADD-ONLY AND IDEMPOTENT: an element is appended only when its id is not
 * already there, so nothing existing is changed or removed, anything edited
 * from the dashboard since is untouched, and a second run adds nothing. Both
 * rows are snapshotted into editorial_migration_backup first.
 *
 * DEPLOY ORDER: after the code (which understands `hidden` on sessions and
 * ships the speakers' photos) is live. Applying it earlier would not break
 * anything, but the sessions would not yet be hidden from the public lists.
 */
insert into public.editorial_migration_backup (migration, document_id, payload)
select '0041', d.id, d.payload
from public.editorial_documents d
where d.id in ('speakers', 'sessions')
on conflict (migration, document_id) do nothing;

update public.editorial_documents d
set payload = d.payload || coalesce((
  select jsonb_agg(x order by o)
  from jsonb_array_elements($wl$[{"id": "akana-signing-josias-aaron", "name": "Akana Signing Josias Aaron", "role": {"fr": "Co-founder & CTO at XyberClan | Software Developer | AI & Cybersecurity Enthusiast | Tech Community Builder", "en": "Co-founder & CTO at XyberClan | Software Developer | AI & Cybersecurity Enthusiast | Tech Community Builder"}, "company": "", "photoUrl": "/speakers/akana-signing-josias-aaron.webp", "bio": {"fr": "I am a Tech Enthusiast, Software Developer, CTO at XyberClan, aspiring Red Team Operator, and student at the University of Yaoundé I. My journey in technology is driven by curiosity, hands-on learning, and a growing focus on AI, cybersecurity and offensive security._x000D_\n_x000D_\nBeyond my technical journey, I actively contribute to building and growing tech communities, creating opportunities for young people to learn, connect, and explore technology. I volunteered at PyCon Cameroon, and I organised and spoke on cloud and cloud security at an AWS x XyberClan x ENSPY event. I also served as a mentor in the GEHMIT PAEI Program pole Cybersecurity, taking learners in the Offensive Security track, where I supported learners in developing practical cybersecurity skills._x000D_\n_x000D_\nThrough XyberClan and my involvement in community initiatives, I aim to make AI and cybersecurity more accessible to young people and encourage them to move beyond theory into hands-on experimentation, continuous learning, and real-world problem solving._x000D_\n_x000D_\nAt DevFest Yaoundé, I will share how young Cameroonians can use free  AI tools to build and ship real products, start a business, and turn an idea into something people can use.", "en": "I am a Tech Enthusiast, Software Developer, CTO at XyberClan, aspiring Red Team Operator, and student at the University of Yaoundé I. My journey in technology is driven by curiosity, hands-on learning, and a growing focus on AI, cybersecurity and offensive security._x000D_\n_x000D_\nBeyond my technical journey, I actively contribute to building and growing tech communities, creating opportunities for young people to learn, connect, and explore technology. I volunteered at PyCon Cameroon, and I organised and spoke on cloud and cloud security at an AWS x XyberClan x ENSPY event. I also served as a mentor in the GEHMIT PAEI Program pole Cybersecurity, taking learners in the Offensive Security track, where I supported learners in developing practical cybersecurity skills._x000D_\n_x000D_\nThrough XyberClan and my involvement in community initiatives, I aim to make AI and cybersecurity more accessible to young people and encourage them to move beyond theory into hands-on experimentation, continuous learning, and real-world problem solving._x000D_\n_x000D_\nAt DevFest Yaoundé, I will share how young Cameroonians can use free  AI tools to build and ship real products, start a business, and turn an idea into something people can use."}, "track": {"fr": "Gemini", "en": "Gemini"}, "day": 1, "sessionIds": ["sz-1345194"], "social": {"linkedin": "https://www.linkedin.com/in/akana-signing-josias-aaron/", "website": "https://www.xyberclan.dev"}, "icebreakerQuestion": {"fr": "Vibe coding: genius or cheating?", "en": "Vibe coding: genius or cheating?"}, "icebreakerAnswer": {"fr": "Genius, if you can still explain and fix what the AI wrote.", "en": "Genius, if you can still explain and fix what the AI wrote."}, "hidden": true}, {"id": "bahanack-georges-yvan", "name": "Bahanack Georges Yvan", "role": {"fr": "Co-founder of SIMBTECH SAS, Bachelor in AI, Computer Engineer", "en": "Co-founder of SIMBTECH SAS, Bachelor in AI, Computer Engineer"}, "company": "", "photoUrl": "/speakers/bahanack-georges-yvan.webp", "bio": {"fr": "**Bahanack Georges Yvan** is a young technology entrepreneur and CEO of **SIMBTECH SAS**, a France-based technology company specializing in Artificial Intelligence, Machine Learning, and software and mobile/web application development._x000D_\n_x000D_\nHe holds a **Bachelor’s degree in Artificial Intelligence** from the **École Supérieure d’Informatique et d’Intelligence Artificielle de Paris (ESIIA Paris)** and is currently a **4th-year Computer Science Engineering student** at the **École Nationale Supérieure Polytechnique de Yaoundé (ENSPY)**._x000D_\n_x000D_\nPassionate about technology and innovation, Georges Yvan focuses on building practical digital solutions and exploring how AI and software engineering can address real-world challenges. Through SIMBTECH, he works at the intersection of **AI, software engineering, entrepreneurship, and digital innovation**._x000D_", "en": "**Bahanack Georges Yvan** is a young technology entrepreneur and CEO of **SIMBTECH SAS**, a France-based technology company specializing in Artificial Intelligence, Machine Learning, and software and mobile/web application development._x000D_\n_x000D_\nHe holds a **Bachelor’s degree in Artificial Intelligence** from the **École Supérieure d’Informatique et d’Intelligence Artificielle de Paris (ESIIA Paris)** and is currently a **4th-year Computer Science Engineering student** at the **École Nationale Supérieure Polytechnique de Yaoundé (ENSPY)**._x000D_\n_x000D_\nPassionate about technology and innovation, Georges Yvan focuses on building practical digital solutions and exploring how AI and software engineering can address real-world challenges. Through SIMBTECH, he works at the intersection of **AI, software engineering, entrepreneurship, and digital innovation**._x000D_"}, "track": {"fr": "AI & ML", "en": "AI & ML"}, "day": 1, "sessionIds": ["sz-1351431"], "social": {"linkedin": "https://www.linkedin.com/in/georges-yvan-bahanack-a78497250/", "website": "https://www.simbtech.fr"}, "icebreakerQuestion": {"fr": "If AI can already write a complete application in seconds, why should you still spend years learning how to code?", "en": "If AI can already write a complete application in seconds, why should you still spend years learning how to code?"}, "icebreakerAnswer": {"fr": "Because the future doesn't belong to developers who can type code the fastest. It belongs to developers who know what to build, why to build it, and how to tell whether what AI built is actually good.", "en": "Because the future doesn't belong to developers who can type code the fastest. It belongs to developers who know what to build, why to build it, and how to tell whether what AI built is actually good."}, "hidden": true}, {"id": "manuel-sokoudjou", "name": "Manuel Sokoudjou", "role": {"fr": "Software Engineer & Founder of SCMCHOST & Creator of AlgoML", "en": "Software Engineer & Founder of SCMCHOST & Creator of AlgoML"}, "company": "", "photoUrl": "/speakers/manuel-sokoudjou.webp", "bio": {"fr": "Manuel Sokoudjou is a Tech Entrepreneur and Software Engineer from Cameroon. He is the founder of SCMCHOST, a professional web hosting and enterprise SMS platform, and the creator of both AlgoML (a custom algorithmic language for seamless code generation) and DjangoForge. Specializing in software language tooling and infrastructure automation, Manuel builds reliable, high-performance systems that empower both businesses and developers across the region.", "en": "Manuel Sokoudjou is a Tech Entrepreneur and Software Engineer from Cameroon. He is the founder of SCMCHOST, a professional web hosting and enterprise SMS platform, and the creator of both AlgoML (a custom algorithmic language for seamless code generation) and DjangoForge. Specializing in software language tooling and infrastructure automation, Manuel builds reliable, high-performance systems that empower both businesses and developers across the region."}, "track": {"fr": "Web", "en": "Web"}, "day": 1, "sessionIds": ["sz-1351517"], "social": {"linkedin": "https://www.linkedin.com/in/manuel-sokoudjou-0a659a2a2", "website": "https://algoml.scmchost.com"}, "icebreakerQuestion": {"fr": "What is your spiciest or funniest developer opinion?", "en": "What is your spiciest or funniest developer opinion?"}, "icebreakerAnswer": {"fr": "Designing a custom programming language and a dedicated VS Code extension is way easier than understanding someone else's undocumented CSS grid!", "en": "Designing a custom programming language and a dedicated VS Code extension is way easier than understanding someone else's undocumented CSS grid!"}, "hidden": true}, {"id": "flora-tsakeu", "name": "Flora Tsakeu", "role": {"fr": "Développeuse web", "en": "Développeuse web"}, "company": "", "photoUrl": "/speakers/flora-tsakeu.webp", "bio": {"fr": "Développeuse backend passionnée par l'écosystème Java Spring Boot, j'aime concevoir des architectures logicielles adaptées aux réalités du terrain. C'est durant mon cursus de formation que j'ai découvert la puissance de l'Ingénierie Dirigée par les Modèles (IDM). Cette révélation m'a poussée à participer à la création initiale d'un outil d'automatisation capable de transformer une logique algorithmique directement en code. Je viens partager ce retour d'expérience pour montrer comment  l'approche par les modèles aide à structurer sa pensée pour franchir plus facilement le cap de l'écriture de code.", "en": "Développeuse backend passionnée par l'écosystème Java Spring Boot, j'aime concevoir des architectures logicielles adaptées aux réalités du terrain. C'est durant mon cursus de formation que j'ai découvert la puissance de l'Ingénierie Dirigée par les Modèles (IDM). Cette révélation m'a poussée à participer à la création initiale d'un outil d'automatisation capable de transformer une logique algorithmique directement en code. Je viens partager ce retour d'expérience pour montrer comment  l'approche par les modèles aide à structurer sa pensée pour franchir plus facilement le cap de l'écriture de code."}, "track": {"fr": "Web", "en": "Web"}, "day": 1, "sessionIds": ["sz-1351517"], "icebreakerQuestion": {"fr": "Quelle est la phrase de développeur que tu as le plus prononcée en situation de crise dans tes débuts d'apprentissage ?", "en": "Quelle est la phrase de développeur que tu as le plus prononcée en situation de crise dans tes débuts d'apprentissage ?"}, "icebreakerAnswer": {"fr": "Je ne sais pas vous, mais moi c'était : « Mais... ça marchait très bien en local ! »", "en": "Je ne sais pas vous, mais moi c'était : « Mais... ça marchait très bien en local ! »"}, "hidden": true}, {"id": "brice-ludovic", "name": "Brice Ludovic", "role": {"fr": "Program Manager at Youth Access", "en": "Program Manager at Youth Access"}, "company": "", "photoUrl": "/speakers/brice-ludovic.webp", "bio": {"fr": "Serial social entrepreneurs with passion to solve the most challenging African challenges : unemployment, hunger and poverty", "en": "Serial social entrepreneurs with passion to solve the most challenging African challenges : unemployment, hunger and poverty"}, "track": {"fr": "Cloud", "en": "Cloud"}, "day": 1, "sessionIds": ["sz-1360167"], "icebreakerQuestion": {"fr": "How will AI impact the job market in Africa ?", "en": "How will AI impact the job market in Africa ?"}, "icebreakerAnswer": {"fr": "For the incompetent the game is over. For the talented and entrepreneurs the sky will be the limit", "en": "For the incompetent the game is over. For the talented and entrepreneurs the sky will be the limit"}, "hidden": true}, {"id": "prosper-nsisse-ihloumam", "name": "Prosper Nsisse Ihloumam", "role": {"fr": "Software & IT Support Engineer Intern, IUSJ Cameroon", "en": "Software & IT Support Engineer Intern, IUSJ Cameroon"}, "company": "", "photoUrl": "/speakers/prosper-nsisse-ihloumam.webp", "bio": {"fr": "Je suis NSISSE IHLOUMAM Prosper, jeune ingénieur logiciel avec un parcours assez constitué. Alors, avec un grand amour pour l'informatique j'ai toujours aimer travailler seul. En progressant, j'ai appris une notion importante : le partage. C'est dans cette optique que j'ai décidé de partager désormais et apprendre des autres.", "en": "Je suis NSISSE IHLOUMAM Prosper, jeune ingénieur logiciel avec un parcours assez constitué. Alors, avec un grand amour pour l'informatique j'ai toujours aimer travailler seul. En progressant, j'ai appris une notion importante : le partage. C'est dans cette optique que j'ai décidé de partager désormais et apprendre des autres."}, "track": {"fr": "AI & ML", "en": "AI & ML"}, "day": 1, "sessionIds": ["sz-1376595"], "icebreakerQuestion": {"fr": "", "en": ""}, "icebreakerAnswer": {"fr": "", "en": ""}, "hidden": true}, {"id": "yufenyuy-fiora-leinyuy", "name": "Yufenyuy Fiora Leinyuy", "role": {"fr": "Educator / Educational Psychology / Philosophy of Education / Research and Flourishing enthusiast", "en": "Educator / Educational Psychology / Philosophy of Education / Research and Flourishing enthusiast"}, "company": "", "photoUrl": "/speakers/yufenyuy-fiora-leinyuy.webp", "bio": {"fr": "A Cameroon-based educator and researcher with a bachelor degree in Educational Psychology and  Master's degree in Philosophy of Education, whose interests span human behaviour, language, social inequality and human flourishing._x000D_\n_x000D_\nWith experience in teaching, research and professional event volunteering, including the Cameroon International Tech Summit 2026, she is interested in exploring the human dimensions of emerging technologies._x000D_\n_x000D_\nHer current intellectual interests focus on how artificial intelligence interacts with language, culture and social conditions, and how technological innovation can expand meaningful opportunities for individuals and communities across Africa._x000D_\n_x000D_\nShe brings an interdisciplinary perspective to conversations about inclusive, responsible and human-centred technological development.", "en": "A Cameroon-based educator and researcher with a bachelor degree in Educational Psychology and  Master's degree in Philosophy of Education, whose interests span human behaviour, language, social inequality and human flourishing._x000D_\n_x000D_\nWith experience in teaching, research and professional event volunteering, including the Cameroon International Tech Summit 2026, she is interested in exploring the human dimensions of emerging technologies._x000D_\n_x000D_\nHer current intellectual interests focus on how artificial intelligence interacts with language, culture and social conditions, and how technological innovation can expand meaningful opportunities for individuals and communities across Africa._x000D_\n_x000D_\nShe brings an interdisciplinary perspective to conversations about inclusive, responsible and human-centred technological development."}, "track": {"fr": "UX/UI Design", "en": "UX/UI Design"}, "day": 1, "sessionIds": ["sz-1376615"], "social": {"linkedin": "https://www.linkedin.com/in/fiora-leinyuy-118504403"}, "icebreakerQuestion": {"fr": "What is one language that artificial intelligence still struggles to understand?", "en": "What is one language that artificial intelligence still struggles to understand?"}, "icebreakerAnswer": {"fr": "The language of human experience. AI can translate our words, but understanding the culture, emotions and realities behind them is another challenge entirely.", "en": "The language of human experience. AI can translate our words, but understanding the culture, emotions and realities behind them is another challenge entirely."}, "hidden": true}]$wl$::jsonb) with ordinality as t(x, o)
  where not exists (
    select 1 from jsonb_array_elements(d.payload) e where e ->> 'id' = x ->> 'id'
  )
), '[]'::jsonb)
where d.id = 'speakers';

update public.editorial_documents d
set payload = d.payload || coalesce((
  select jsonb_agg(x order by o)
  from jsonb_array_elements($wl$[{"id": "sz-1345194", "day": 1, "kind": "workshop", "level": "intermediate", "language": ["fr", "en"], "originalLanguage": "en", "title": {"fr": "Build and Ship Your Product Today: Start Your Business with Free AI Tools", "en": "Build and Ship Your Product Today: Start Your Business with Free AI Tools"}, "description": {"fr": "Everyone has an idea. Few people ship it. In this session, I'll show you how to go from idea to a working product using free AI tools, live on stage._x000D_\n_x000D_\nYou'll see three skills in action:_x000D_\n_x000D_\nPrompt engineering: getting reliable, usable results _x000D_\nVibe coding: building a working app by directing AI_x000D_\nAgentic engineering: an introduction to AI agents, and how to build a simple first agent that automates one task in your business_x000D_\n_x000D_\nThen we'll cover the business side: how to test your product with real users and what to do in your first week._x000D_\n_x000D_\nYou will leave with a clear workflow and a first project to start tomorrow. No prior AI experience needed._x000D_\n_x000D_\nTout le monde a une idée. Peu la concrétisent. Dans cette session, je vous montre comment passer de l'idée à un produit fonctionnel avec les outils d'IA gratuits de Google, en direct : prompt engineering , vibe coding et une introduction aux agents IA, avec un premier agent simple qui automatise une tâche de votre business. Puis nous verrons comment tester votre produit avec de vrais utilisateurs. Vous repartez avec un workflow clair et un premier projet à lancer dès demain.", "en": "Everyone has an idea. Few people ship it. In this session, I'll show you how to go from idea to a working product using free AI tools, live on stage._x000D_\n_x000D_\nYou'll see three skills in action:_x000D_\n_x000D_\nPrompt engineering: getting reliable, usable results _x000D_\nVibe coding: building a working app by directing AI_x000D_\nAgentic engineering: an introduction to AI agents, and how to build a simple first agent that automates one task in your business_x000D_\n_x000D_\nThen we'll cover the business side: how to test your product with real users and what to do in your first week._x000D_\n_x000D_\nYou will leave with a clear workflow and a first project to start tomorrow. No prior AI experience needed._x000D_\n_x000D_\nTout le monde a une idée. Peu la concrétisent. Dans cette session, je vous montre comment passer de l'idée à un produit fonctionnel avec les outils d'IA gratuits de Google, en direct : prompt engineering , vibe coding et une introduction aux agents IA, avec un premier agent simple qui automatise une tâche de votre business. Puis nous verrons comment tester votre produit avec de vrais utilisateurs. Vous repartez avec un workflow clair et un premier projet à lancer dès demain."}, "track": {"fr": "Gemini", "en": "Gemini"}, "tags": [{"fr": "Gemini", "en": "Gemini"}, {"fr": "AI", "en": "AI"}, {"fr": "Web", "en": "Web"}, {"fr": "Mobile", "en": "Mobile"}, {"fr": "UX/UI Design", "en": "UX/UI Design"}, {"fr": "DevOps", "en": "DevOps"}], "speakerIds": ["akana-signing-josias-aaron"], "hidden": true}, {"id": "sz-1351431", "day": 1, "kind": "talk", "lightning": true, "level": "advanced", "language": ["fr", "en"], "originalLanguage": "en", "title": {"fr": "AI Is Changing the Developer: What Should We Learn Now?", "en": "AI Is Changing the Developer: What Should We Learn Now?"}, "description": {"fr": "How AI is changing software development._x000D_\nWhy knowing how to code still matters._x000D_\nAI-assisted development vs. understanding fundamentals._x000D_\nPrompt engineering, AI APIs, local models and agents._x000D_\nHow students and young developers can use AI without becoming dependent on it._x000D_\nWhat skills will differentiate developers in the next 5 years.", "en": "How AI is changing software development._x000D_\nWhy knowing how to code still matters._x000D_\nAI-assisted development vs. understanding fundamentals._x000D_\nPrompt engineering, AI APIs, local models and agents._x000D_\nHow students and young developers can use AI without becoming dependent on it._x000D_\nWhat skills will differentiate developers in the next 5 years."}, "track": {"fr": "AI & ML", "en": "AI & ML"}, "tags": [{"fr": "AI & ML", "en": "AI & ML"}, {"fr": "Mobile", "en": "Mobile"}, {"fr": "UX/UI Design", "en": "UX/UI Design"}, {"fr": "Gemini", "en": "Gemini"}, {"fr": "AI", "en": "AI"}, {"fr": "Web", "en": "Web"}], "speakerIds": ["bahanack-georges-yvan"], "hidden": true}, {"id": "sz-1351517", "day": 1, "kind": "workshop", "level": "introductory", "language": ["fr", "en"], "originalLanguage": "en", "title": {"fr": "AlgoML: An algorithmic language for seamless logic design and instant code generation", "en": "AlgoML: An algorithmic language for seamless logic design and instant code generation"}, "description": {"fr": "Learning how to program can be tough, especially when transitioning from theoretical pseudo-code to rigid programming syntax. To solve this, I created AlgoML—a custom language designed to accelerate how we learn and compile programming logic._x000D_\nIn this practical, demo-driven session, you will discover how to use AlgoML to:_x000D_\n1. Design Clean Logic: Write clear, human-readable algorithms using a syntax built specifically for learning._x000D_\n2. Get Real-Time Guidance: Use a dedicated VS Code extension that guides you with autocompletion and instant feedback._x000D_\n3. Generate Production Code: Compile your algorithms instantly into clean, ready-to-run Python, C, and Java code with a single command._x000D_\nIf you are a student looking to master programming logic, an educator seeking better teaching tools, or a developer curious about custom dev tools, this session will show you how AlgoML bridges the gap between pure logic and executable code.", "en": "Learning how to program can be tough, especially when transitioning from theoretical pseudo-code to rigid programming syntax. To solve this, I created AlgoML—a custom language designed to accelerate how we learn and compile programming logic._x000D_\nIn this practical, demo-driven session, you will discover how to use AlgoML to:_x000D_\n1. Design Clean Logic: Write clear, human-readable algorithms using a syntax built specifically for learning._x000D_\n2. Get Real-Time Guidance: Use a dedicated VS Code extension that guides you with autocompletion and instant feedback._x000D_\n3. Generate Production Code: Compile your algorithms instantly into clean, ready-to-run Python, C, and Java code with a single command._x000D_\nIf you are a student looking to master programming logic, an educator seeking better teaching tools, or a developer curious about custom dev tools, this session will show you how AlgoML bridges the gap between pure logic and executable code."}, "track": {"fr": "Web", "en": "Web"}, "tags": [{"fr": "Web", "en": "Web"}], "speakerIds": ["manuel-sokoudjou", "flora-tsakeu"], "hidden": true}, {"id": "sz-1360167", "day": 1, "kind": "workshop", "online": true, "level": "intermediate", "language": ["fr", "en"], "originalLanguage": "en", "title": {"fr": "Scaling an AI powered ERP for SMBs in Cameroon - Our experience @Genuka", "en": "Scaling an AI powered ERP for SMBs in Cameroon - Our experience @Genuka"}, "description": {"fr": "Genuka CTO will share his experience, architecture, tech stack, key datas, GTM, challenges and tips on how we grew our AI powered ERP adoption amongst 100+ SMB owners in Cameroon", "en": "Genuka CTO will share his experience, architecture, tech stack, key datas, GTM, challenges and tips on how we grew our AI powered ERP adoption amongst 100+ SMB owners in Cameroon"}, "track": {"fr": "Cloud", "en": "Cloud"}, "tags": [{"fr": "Cloud", "en": "Cloud"}, {"fr": "DevOps", "en": "DevOps"}, {"fr": "AI", "en": "AI"}], "speakerIds": ["brice-ludovic"], "hidden": true}, {"id": "sz-1376595", "day": 1, "kind": "talk", "lightning": true, "level": "introductory", "language": ["fr"], "originalLanguage": "fr", "title": {"fr": "Qui est le véritable développeur à l'ère de l'IA ? L'imposture du temps et le piège de la vitesse.", "en": "Qui est le véritable développeur à l'ère de l'IA ? L'imposture du temps et le piège de la vitesse."}, "description": {"fr": "Alors, je me suis surpris moi-même à ne plus relire 100 % du code généré par l'IA avant de push en prod. Et autour de moi, la crainte est bien réelle. Je vois arriver une génération de juniors capables de sortir une application complexe en trois heures grâce aux LLMs, mais totalement démunis, les yeux écarquillés, quand le système pète et qu'il faut expliquer un stack trace de base._x000D_\n_x000D_\nDans notre industrie, la vitesse est devenue un dogme. Pire encore, nous détruisons le temps générationnel. En privant les débutants des \"temps morts\" et des galères formatrices, là où se forge la mémoire musculaire du code, nous créons une fracture irréparable entre des seniors bâtis sur les fondations et des juniors condamnés à être de simples exécutants sous assistance algorithmique._x000D_\n_x000D_\nCe talk propose une remise en question sans filtre de notre métier à l'ère de l'IA générative. L'IA est en train de créer une génération de développeurs handicapés mentaux sous prétexte de productivité, en nous faisant croire que le véritable développeur est le Prompt Engineer.", "en": "Alors, je me suis surpris moi-même à ne plus relire 100 % du code généré par l'IA avant de push en prod. Et autour de moi, la crainte est bien réelle. Je vois arriver une génération de juniors capables de sortir une application complexe en trois heures grâce aux LLMs, mais totalement démunis, les yeux écarquillés, quand le système pète et qu'il faut expliquer un stack trace de base._x000D_\n_x000D_\nDans notre industrie, la vitesse est devenue un dogme. Pire encore, nous détruisons le temps générationnel. En privant les débutants des \"temps morts\" et des galères formatrices, là où se forge la mémoire musculaire du code, nous créons une fracture irréparable entre des seniors bâtis sur les fondations et des juniors condamnés à être de simples exécutants sous assistance algorithmique._x000D_\n_x000D_\nCe talk propose une remise en question sans filtre de notre métier à l'ère de l'IA générative. L'IA est en train de créer une génération de développeurs handicapés mentaux sous prétexte de productivité, en nous faisant croire que le véritable développeur est le Prompt Engineer."}, "track": {"fr": "AI & ML", "en": "AI & ML"}, "tags": [{"fr": "AI & ML", "en": "AI & ML"}, {"fr": "AI", "en": "AI"}, {"fr": "Business", "en": "Business"}], "speakerIds": ["prosper-nsisse-ihloumam"], "hidden": true}, {"id": "sz-1376615", "day": 1, "kind": "talk", "lightning": true, "level": "introductory", "language": ["en"], "originalLanguage": "en", "title": {"fr": "Beyond the algorithm: who's language? Who's future", "en": "Beyond the algorithm: who's language? Who's future"}, "description": {"fr": "What happens when an AI system produces the right answer, but the people it was designed to serve cannot meaningfully benefit from it?_x000D_\n_x000D_\nAs artificial intelligence transforms education, healthcare and everyday life, technological performance is increasingly celebrated. Yet important questions remain: Whose language does AI understand? Whose experiences shape its design? And who ultimately benefits from its advancement?_x000D_\n_x000D_\nIn linguistically and culturally diverse African societies, these questions are particularly important. Language is more than a means of communication. It shapes identity, learning, participation and access to knowledge. Beyond language, psychological and social factors such as confidence, trust, digital literacy and inequality influence how people interact with emerging technologies._x000D_\n_x000D_\nDrawing on educational psychology and philosophy of education, this session explores the relationship between language, human behaviour and human flourishing in AI development._x000D_\n_x000D_\nThrough relatable examples from African educational and social contexts, participants will explore a practical three-part framework for evaluating human-centred AI: Understanding, Participation and Flourishing._x000D_\n_x000D_\nThe session will demonstrate how developers can incorporate linguistic inclusion, user experiences and meaningful human outcomes into their design and evaluation processes._x000D_\n_x000D_\nUltimately, the presentation challenges us to look beyond what AI can accomplish technologically and consider what it enables people to understand, become and achieve._x000D_\n_x000D_\nBecause the real measure of intelligent innovation is not simply how well our machines perform, but how meaningfully they improve human lives.", "en": "What happens when an AI system produces the right answer, but the people it was designed to serve cannot meaningfully benefit from it?_x000D_\n_x000D_\nAs artificial intelligence transforms education, healthcare and everyday life, technological performance is increasingly celebrated. Yet important questions remain: Whose language does AI understand? Whose experiences shape its design? And who ultimately benefits from its advancement?_x000D_\n_x000D_\nIn linguistically and culturally diverse African societies, these questions are particularly important. Language is more than a means of communication. It shapes identity, learning, participation and access to knowledge. Beyond language, psychological and social factors such as confidence, trust, digital literacy and inequality influence how people interact with emerging technologies._x000D_\n_x000D_\nDrawing on educational psychology and philosophy of education, this session explores the relationship between language, human behaviour and human flourishing in AI development._x000D_\n_x000D_\nThrough relatable examples from African educational and social contexts, participants will explore a practical three-part framework for evaluating human-centred AI: Understanding, Participation and Flourishing._x000D_\n_x000D_\nThe session will demonstrate how developers can incorporate linguistic inclusion, user experiences and meaningful human outcomes into their design and evaluation processes._x000D_\n_x000D_\nUltimately, the presentation challenges us to look beyond what AI can accomplish technologically and consider what it enables people to understand, become and achieve._x000D_\n_x000D_\nBecause the real measure of intelligent innovation is not simply how well our machines perform, but how meaningfully they improve human lives."}, "track": {"fr": "UX/UI Design", "en": "UX/UI Design"}, "tags": [{"fr": "UX/UI Design", "en": "UX/UI Design"}, {"fr": "Data Science", "en": "Data Science"}, {"fr": "AI", "en": "AI"}], "speakerIds": ["yufenyuy-fiora-leinyuy"], "hidden": true}]$wl$::jsonb) with ordinality as t(x, o)
  where not exists (
    select 1 from jsonb_array_elements(d.payload) e where e ->> 'id' = x ->> 'id'
  )
), '[]'::jsonb)
where d.id = 'sessions';
